from fastchat.model.model_adapter import load_model, get_conversation_template, add_model_args

# Code adapter for models that use a separate tokenizer
class ExampleAdapter(BaseModelAdapter):
    use_fast_tokenizer = False

    def match(self, model_path: str):
        return "example" in model_path.lower()

    def load_model(self, model_path: str, from_pretrained_kwargs: dict):
        revision = from_pretrained_kwargs.get("revision", "main")
        tokenizer = AutoTokenizer.from_pretrained(model_path, use_fast=self.use_fast_tokenizer, revision=revision)
        model = AutoModelForCausalLM.from_pretrained(
            model_path,
            low_cpu_mem_usage=True,
            **from_pretrained_kwargs,
        )
        return model, tokenizer

    def get_default_conv_template(self, model_path: str) -> Conversation:
        return get_conv_template("vicuna_v1.1")


# Register the adapter
register_model_adapter(ExampleAdapter())

