# spectral risk gap
class SpectralGap(torch.nn.Module):
    def __init__(self, taus):
        super().__init__(); self.taus = torch.tensor(taus)[None,None,:]  # [1,1,Q]
    def forward(self, q_w, q_l, psi):
        # q_*: [B,K,Q] quantiles, psi: [B,1,Q]
        diff = q_w - q_l  # [B,K,Q]
        worst = diff.max(dim=1).values  # [B,Q]
        return (psi * worst).sum(dim=-1)  # [B]

def make_psi(user_feat, Q):
